class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)  # dp[0] is 0 extra characters

        for i in range(1, n + 1):
            # Initialize with previous character + 1 (current character is extra)
            dp[i] = dp[i-1] + 1

            # Check all words in dictionary
            for word in dictionary:
                l = len(word)
                if l <= i:
                    if s[i - l : i] == word:
                        # compare with dp[i - l]
                        if dp[i - l] < dp[i]:
                            dp[i] = dp[i - l]

        return dp[n]

