class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        class SegmentTree:
            def __init__(self, data):
                self.n = len(data)
                self.size = 1
                while self.size < self.n:
                    self.size <<= 1
                self.tree = [ -float('inf') ] * (2 * self.size)
                # fill leaves
                for i in range(self.n):
                    self.tree[self.size + i] = data[i]
                # build the tree
                for i in range(self.size - 1, 0, -1):
                    self.tree[i] = max(self.tree[2*i], self.tree[2*i + 1])

            def update(self, pos, value):
                pos += self.size
                self.tree[pos] = value
                pos //= 2
                while pos >= 1:
                    new_val = max(self.tree[2*pos], self.tree[2*pos + 1])
                    if self.tree[pos] == new_val:
                        break
                    self.tree[pos] = new_val
                    pos //= 2

            def find_leftmost(self, x):
                res = self._find(1, 0, self.size, x)
                return res

            def _find(self, node, node_left, node_right, x):
                if self.tree[node] < x:
                    return -1
                if node_left == node_right - 1:
                    return node_left
                mid = (node_left + node_right) // 2
                # check left child first
                left_res = self._find(2*node, node_left, mid, x)
                if left_res != -1:
                    return left_res
                return self._find(2*node + 1, mid, node_right, x)

        st = SegmentTree(baskets)
        unplaced = 0
        for fruit in fruits:
            idx = st.find_leftmost(fruit)
            if idx == -1:
                unplaced += 1
            else:
                st.update(idx, -float('inf'))
        return unplaced

