    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                i -= 1
            if i == -1:
                return '0'
            s_list[i] = str(int(s_list[i]) - 1)
            for j in range(i + 1, len(s_list)):
                s_list[j] = '9'
            res = ''.join(s_list).lstrip('0')
            if not res:
                return '0'
            return res

        def count(s: str) -> int:
            digits = list(map(int, s))
            n = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev, leading_zero, tight):
                if pos == n:
                    return 1
                ub = digits[pos] if tight else 9
                res = 0
                for d in range(0, ub + 1):
                    new_tight = tight and (d == ub)
                    new_leading_zero = leading_zero and (d == 0)
                    if new_leading_zero:
                        res += dp(pos + 1, 0, new_leading_zero, new_tight)
                    else:
                        if leading_zero and d != 0:
                            res += dp(pos + 1, d, False, new_tight)
                        else:
                            if abs(d - prev) == 1:
                                res += dp(pos + 1, d, False, new_tight)
                    res %= MOD
                return res % MOD

            return dp(0, 0, True, True)

        high_count = count(high)
        low_minus_1 = subtract_one(low)
        low_minus_1_count = count(low_minus_1)
        ans = (high_count - low_minus_1_count) % MOD
        return ans

