class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        ss = s + s
        m = len(t)

        # Compute prefix array for KMP
        pi = [0] * m
        for i in range(1, m):
            j = pi[i-1]
            while j > 0 and t[i] != t[j]:
                j = pi[j-1]
            if t[i] == t[j]:
                j += 1
            pi[i] = j

        # Find all occurrences of t in ss
        occurrences = []
        j = 0  # current length of the prefix
        for i in range(len(ss)):
            while j > 0 and ss[i] != t[j]:
                j = pi[j-1]
            if ss[i] == t[j]:
                j += 1
            if j == m:
                occurrences.append(i - m + 1)
                j = pi[j-1]

        # Collect target rotations
        target_rs = []
        for pos in occurrences:
            if 0 <= pos < n:
                r = (n - pos) % n
                target_rs.append(r)

        if not target_rs:
            return 0

        # Compute required values
        inv_n = pow(n, MOD - 2, MOD)
        pow_n_1k = pow(n - 1, k, MOD)
        sign_mod = 1 if (k % 2 == 0) else MOD - 1

        total = 0
        for r in target_rs:
            if r == 0:
                numerator = (sign_mod * (n - 1) + pow_n_1k) % MOD
            else:
                numerator = (pow_n_1k - sign_mod) % MOD
            term = (numerator * inv_n) % MOD
            total = (total + term) % MOD

        return total

