class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        dp = {0: 0}  # initial state: no cells selected, sum 0
        for row in grid:
            new_dp = {}
            for mask in dp:
                current_sum = dp[mask]
                # Option 1: do not take any cell in this row
                if mask in new_dp:
                    if current_sum > new_dp[mask]:
                        new_dp[mask] = current_sum
                else:
                    new_dp[mask] = current_sum
                # Option 2: take each cell in this row
                for val in row:
                    if not (mask & (1 << (val - 1))):  # val not in mask
                        new_mask = mask | (1 << (val - 1))
                        new_sum = current_sum + val
                        if new_mask in new_dp:
                            if new_sum > new_dp[new_mask]:
                                new_dp[new_mask] = new_sum
                        else:
                            new_dp[new_mask] = new_sum
            dp = new_dp
        # Find the maximum score excluding the mask 0 (no cells selected)
        max_score = 0
        for mask, score in dp.items():
            if mask != 0 and score > max_score:
                max_score = score
        return max_score

