class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def is_almost_equal(a: int, b: int) -> bool:
            if a == b:
                return True
            a_str = str(a)
            b_str = str(b)
            if len(a_str) == len(b_str):
                diff = []
                for i in range(len(a_str)):
                    if a_str[i] != b_str[i]:
                        diff.append(i)
                if len(diff) == 2:
                    i, j = diff
                    return a_str[i] == b_str[j] and a_str[j] == b_str[i]
                else:
                    return False
            else:
                # Determine which is longer and the target shorter value
                if len(a_str) < len(b_str):
                    longer_str = str(b)
                    shorter_val = a
                else:
                    longer_str = str(a)
                    shorter_val = b
                n = len(longer_str)
                for i in range(n):
                    for j in range(i + 1, n):
                        temp = list(longer_str)
                        temp[i], temp[j] = temp[j], temp[i]
                        swapped_num = int(''.join(temp))
                        if swapped_num == shorter_val:
                            return True
                return False

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if is_almost_equal(nums[i], nums[j]):
                    count += 1
        return count

