class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        # Preprocess each row to contain unique values
        rows = []
        for row in grid:
            rows.append(list(set(row)))

        @lru_cache(maxsize=None)
        def dp(i, mask):
            if i == m:
                return 0
            # Maximum score without taking any cell in the current row
            max_score = dp(i + 1, mask)
            # Try taking each unique value in the current row
            for val in rows[i]:
                if not (mask & (1 << val)):
                    new_mask = mask | (1 << val)
                    current = val + dp(i + 1, new_mask)
                    if current > max_score:
                        max_score = current
            return max_score

        return dp(0, 0)

