class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        from collections import deque

        def generate_palindromes():
            # Helper function to generate all palindromic numbers less than 10^9
            palindromes = set()
            # Generate all palindromes with 1 to 9 digits
            for d in range(1, 10):  # 1-digit
                palindromes.add(d)
            for d in range(1, 100):  # 2-digit
                s = str(d)
                if len(s) == 2:
                    palindromes.add(int(s))
                else:
                    palindromes.add(int(s + s))
            for d in range(1, 1000):  # 3-digit and more
                s = str(d)
                if len(s) == 3:
                    palindromes.add(int(s))
                else:
                    palindromes.add(int(s + s[-2::-1]))
                if len(s) == 4:
                    palindromes.add(int(s))
                else:
                    palindromes.add(int(s + s[-1::-1]))
            return sorted(palindromes)

        palindromes = generate_palindromes()
        n = len(nums)

        # Find the median of nums to minimize the sum of absolute differences
        nums_sorted = sorted(nums)
        median = nums_sorted[n // 2]

        # Find the closest palindromes to the median
        candidates = []
        for i in range(len(palindromes)):
            if palindromes[i] >= median:
                candidates.append(palindromes[i])
                if i > 0:
                    candidates.append(palindromes[i - 1])
                break

        # Evaluate cost for each candidate
        min_cost = float('inf')
        for p in candidates:
            cost = sum(abs(num - p) for num in nums)
            min_cost = min(min_cost, cost)

        return min_cost

