        from collections import Counter

        def get_digit_count(n):
            digits = [0] * 10
            for ch in str(n):
                digits[int(ch)] += 1
            return tuple(digits)

        def can_become_equal(s1, s2):
            count1 = get_digit_count(s1)
            count2 = get_digit_count(s2)
            if count1 == count2:
                return True
            # Try swapping one pair of digits in s1
            s1_str = list(str(s1))
            for i in range(len(s1_str)):
                for j in range(i + 1, len(s1_str)):
                    s1_str[i], s1_str[j] = s1_str[j], s1_str[i]
                    if get_digit_count(''.join(s1_str)) == count2:
                        return True
                    s1_str[i], s1_str[j] = s1_str[j], s1_str[i]  # backtrack
            return False

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if can_become_equal(nums[i], nums[j]):
                    count += 1
        return count

