        for i in range(n):
            for j in range(i + 1, n):
                x1, y1 = coordinates[i]
                x2, y2 = coordinates[j]
                if x1 < x2 and y1 < y2:
                    graph[i].append(j)
                elif x2 < x1 and y2 < y1:
                    graph[j].append(i)

        # Memoization cache for DP
        dp = [1] * n

        # Run DFS for all nodes and compute longest increasing path
        def dfs(u):
            if dp[u] != 1:
                return dp[u]
            for v in graph[u]:
                dp[u] = max(dp[u], 1 + dfs(v))
            return dp[u]

        # Run DFS from all nodes
        for i in range(n):
            dfs(i)

        # Return the value of the path that includes the k-th point
        return dp[k]

