                    new_leading_zero = leading_zero and d == 0
                    if not is_num and d == 0:
                        res += dp(pos + 1, prev_digit, new_tight, new_is_num, new_leading_zero)
                    elif not is_num:
                        res += dp(pos + 1, d, new_tight, new_is_num, new_leading_zero)
                    else:
                        if abs(d - prev_digit) == 1:
                            res += dp(pos + 1, d, new_tight, new_is_num, new_leading_zero)
                    res %= MOD
                return res

            return dp(0, 0, True, False, True)

        def is_stepping_number(n: str) -> bool:
            for i in range(1, len(n)):
                if abs(int(n[i]) - int(n[i - 1])) != 1:
