            for d in range(1, 10):
                num = str(d)
                for _ in range(length - 1):
                    last_digit = int(num[-1])
                    if last_digit > 0:
                        num += str(last_digit - 1)
                    if last_digit < 9:
                        num += str(last_digit + 1)
                    stepping.add(num)
                    num = num[:-1]
            return stepping

        # Use digit DP for high
        total_high = count_stepping_numbers(high)

        # Adjust for low
        if is_stepping_number(low):
            total_high -= 1

        # Subtract count of stepping numbers less than low
        def count_less_than(upper: str) -> int:
            from functools import lru_cache

            @lru_cache(None)
            def dp(pos: int, prev_digit: int, tight: bool, is_num: bool, leading_zero: bool) -> int:
                if pos == len(upper):
