                    elif not leading_zero:
                        if prev_digit == -1 or abs(d - prev_digit) == 1:
                            res += dp(pos + 1, d, new_tight, new_leading_zero)
                    res %= MOD

                return res

            return dp(0, -1, True, True)

        def is_stepping_number(num: str) -> bool:
