class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Precompute all rotations of s and map them to their indices
        s_rotations = s + s
        rotation_map = dict()
        for i in range(n):
            rotation = s_rotations[i:i+n]
            if rotation not in rotation_map:
                rotation_map[rotation] = []
            rotation_map[rotation].append(i)

        # Check if t is a rotation of s
        if t not in rotation_map:
            return 0
        valid_rotations = rotation_map[t]

        # Precompute the number of ways to get from rotation l to rotation r in one operation
        # This is 1 if l != r and 0 otherwise (since you can't choose l == n-1 or l == 0)
        def count_transitions():
            trans = [[0]*n for _ in range(n)]
            for l in range(n):
                for r in range(n):
                    if (l - r) % n != 0 and (l - r) % n != n - 1:
                        trans[l][r] = 1
            return trans

        # Matrix exponentiation to compute trans^k
        def matrix_mult(a, b):
            n = len(a)
            res = [[0]*n for _ in range(n)]
            for i in range(n):
                for k in range(n):
                    if a[i][k] == 0:
                        continue
                    for j in range(n):
                        res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
            return res

        def matrix_pow(mat, power):
            n = len(mat)
            result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
            while power:
                if power % 2 == 1:
                    result = matrix_mult(result, mat)
                mat = matrix_mult(mat, mat)
                power //= 2
            return result

        # Build identity matrix for initial state (s is at rotation 0)
        initial = [0]*n
        initial[0] = 1

        trans = count_transitions()
        trans_k = matrix_pow(trans, k)

        # Compute final result: sum over all valid rotations of trans_k[0][r]
        result = 0
        for r in valid_rotations:
            result = (result + trans_k[0][r]) % MOD

        return result

class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from collections import defaultdict
        import bisect

        n = len(coordinates)
        required_point = coordinates[k]

        # Sort coordinates for efficient searching
        sorted_by_x = sorted((x, y, i) for i, (x, y) in enumerate(coordinates))
        sorted_by_y = sorted((y, x, i) for i, (x, y) in enumerate(coordinates))

        # Build maps from x and y to list of (other, index) sorted
        x_map = defaultdict(list)
        y_map = defaultdict(list)

        for x, y, i in sorted_by_x:
            x_map[x].append((y, i))
        for y, x, i in sorted_by_y:
            y_map[y].append((x, i))

        # Memoization cache for dp
        memo = {}

        def dp(x, y, i):
            if (x, y, i) in memo:
                return memo[(x, y, i)]
            max_len = 1
            # Find all points with x' > x and y' > y
            idx = bisect.bisect_right(x_map[x], (y, i))  # exclude self
            for yy, ii in x_map[x][idx:]:
                if yy > y:
                    max_len = max(max_len, 1 + dp(x, y, ii))
            for xx in x_map:
                if xx > x:
                    idx = bisect.bisect_right(x_map[xx], (y, i))
                    for yy, ii in x_map[xx][idx:]:
                        if yy > y:
                            max_len = max(max_len, 1 + dp(xx, yy, ii))
            memo[(x, y, i)] = max_len
            return max_len

        return dp(required_point[0], required_point[1], k)

