class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        count = 0
        res = []

        for idx, color in queries:
            old_color = nums[idx]

            # Subtract contributions from old color
            for direction in (-1, 1):
                neighbor_idx = idx + direction
                if 0 <= neighbor_idx < n:
                    if old_color != 0 and nums[neighbor_idx] == old_color:
                        count -= 1

            # Update the color
            nums[idx] = color

            # Add contributions from new color
            for direction in (-1, 1):
                neighbor_idx = idx + direction
                if 0 <= neighbor_idx < n:
                    if nums[neighbor_idx] == color:
                        count += 1

            res.append(count)

