        prev_or = set()
        for num in nums:
            curr_or = {num}
            for val in prev_or:
                curr_or.add(val | num)
            # Update the minimum difference
            for val in curr_or:
                current_diff = abs(val - k)
                if current_diff < min_diff:
                    min_diff = current_diff
