    def is_almost_equal(self, x: int, y: int) -> bool:
        if x == y:
            return True
        x_str = str(x)
        y_str = str(y)

        # Check swaps in x
        for i in range(len(x_str)):
            for j in range(i + 1, len(x_str)):
                lst = list(x_str)
                lst[i], lst[j] = lst[j], lst[i]
                new_s = ''.join(lst)
                if int(new_s) == y:
                    return True

        # Check swaps in y
        for i in range(len(y_str)):
            for j in range(i + 1, len(y_str)):
                lst = list(y_str)
                lst[i], lst[j] = lst[j], lst[i]
                new_s = ''.join(lst)
                if int(new_s) == x:
                    return True

        return False

