class Solution:
    def maximumTotalDamage(self, power: List[int]) -> int:
        counts = Counter(power)
        sorted_values = sorted(counts.keys())
        n = len(sorted_values)
        if n == 0:
            return 0
        dp = [0] * n
        dp[0] = counts[sorted_values[0]] * sorted_values[0]
        for i in range(1, n):
            current_val = sorted_values[i]
            prev_val = sorted_values[i-1]
            diff = current_val - prev_val
            current_total = counts[current_val] * current_val
            if diff > 2:
                dp[i] = dp[i-1] + current_total
            else:
                if i >= 2:
                    option2 = dp[i-2] + current_total
                else:
                    option2 = current_total
                dp[i] = max(dp[i-1], option2)
        return dp[-1]

