class Solution:
    def countPairs(self, nums: List[int]) -> int:
        # Precompute swap sets for each number
        swap_sets = []
        for num in nums:
            s = list(str(num))
            n = len(s)
            possible = set()
            for i in range(n):
                for j in range(i + 1, n):
                    # Swap digits at positions i and j
                    s[i], s[j] = s[j], s[i]
                    new_num = int(''.join(s))
                    possible.add(new_num)
                    # Swap back to original state
                    s[i], s[j] = s[j], s[i]
            swap_sets.append(possible)

        count = 0
        # Iterate through all pairs (i, j) where i < j
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] == nums[j]:
                    count += 1
                else:
                    if (nums[j] in swap_sets[i]) or (nums[i] in swap_sets[j]):
                        count += 1
        return count

