    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    M = int(input[ptr])
    ptr += 1

    rows = set()
    columns = set()
    sum_diag = set()
    diff_diag = set()

    for _ in range(M):
        a = int(input[ptr])
        ptr += 1
        b = int(input[ptr])
        ptr += 1
        rows.add(a)
        columns.add(b)
        sum_diag.add(a + b)
        diff_diag.add(a - b)

    # Calculate individual terms
    term_R = len(rows) * N
    term_C = len(columns) * N

    term_S = 0
    for s in sum_diag:
        if s < 2 or s > 2 * N:
            continue
        if s <= N + 1:
            term_S += s - 1
        else:
            term_S += 2 * N - s + 1

    term_D = 0
    for d in diff_diag:
        if abs(d) >= N:
            continue
        term_D += (N - abs(d))

    # Pairwise intersections
    pair_rc = len(rows) * len(columns)
    pair_rs = 0
    for r in rows:
        for s in sum_diag:
            j = s - r
            if 1 <= j <= N:
                pair_rs += 1
    pair_rd = 0
    for r in rows:
        for d in diff_diag:
            j = r - d
            if 1 <= j <= N:
                pair_rd += 1
    pair_cs = 0
    for c in columns:
        for s in sum_diag:
            i = s - c
            if 1 <= i <= N:
                pair_cs += 1
    pair_cd = 0
    for c in columns:
        for d in diff_diag:
            i = c + d
            if 1 <= i <= N:
                pair_cd += 1
    pair_sd = 0
    for s in sum_diag:
        for d in diff_diag:
            if (s + d) % 2 == 0:
                i = (s + d) // 2
                j = (s - d) // 2
                if 1 <= i <= N and 1 <= j <= N:
                    pair_sd += 1
    sum_pair = pair_rc + pair_rs + pair_rd + pair_cs + pair_cd + pair_sd

    # Triple intersections
    triple_r_c_s = 0
    for r in rows:
        for c in columns:
            s = r + c
            if s in sum_diag:
                triple_r_c_s += 1
    triple_r_c_d = 0
    for r in rows:
        for c in columns:
            d = r - c
            if d in diff_diag:
                triple_r_c_d += 1
    triple_r_s_d = 0
    for r in rows:
        for s in sum_diag:
            d = 2 * r - s
            if d in diff_diag:
                triple_r_s_d += 1
    triple_c_s_d = 0
    for c in columns:
        for s in sum_diag:
            d = s - 2 * c
            if d in diff_diag:
                triple_c_s_d += 1
    sum_triple = triple_r_c_s + triple_r_c_d + triple_r_s_d + triple_c_s_d

    # Quadruple intersection
    quadruple = 0
    for r in rows:
        for c in columns:
            s = r + c
            d = r - c
            if s in sum_diag and d in diff_diag:
                quadruple += 1

    total_forbidden = (term_R + term_C + term_S + term_D) - sum_pair + sum_triple - quadruple
    answer = N * N - total_forbidden
    print(answer)

