class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)  # dp[i] is the minimum extra characters up to index i

        # Preprocess dictionary into a set for O(1) lookups
        word_set = set(dictionary)

        for i in range(1, n + 1):
            # If the substring ending at i is in the dictionary, we can take it
            if s[:i] in word_set:
                dp[i] = 0
            else:
                # Otherwise, we consider the previous state and add one extra character
                dp[i] = dp[i - 1] + 1

                # Check all possible substrings ending at i
                for j in range(i - 1, -1, -1):
                    if s[j:i] in word_set:
                        dp[i] = min(dp[i], dp[j])
                        break  # Once we find a valid word, no need to check further

        return dp[n]

