class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7
        from collections import deque

        def is_stepping(num_str):
            for i in range(1, len(num_str)):
                if abs(int(num_str[i]) - int(num_str[i-1])) != 1:
                    return False
            return True

        def generate_stepping_numbers(length):
            queue = deque()
            for d in range(1, 10):  # no leading zero
                queue.append(str(d))
            while queue:
                num_str = queue.popleft()
                if len(num_str) == length:
                    continue
                last_digit = int(num_str[-1])
                for next_digit in [last_digit - 1, last_digit + 1]:
                    if 0 <= next_digit <= 9:
                        new_num = num_str + str(next_digit)
                        queue.append(new_num)
            return queue

        result = 0
        for length in range(1, len(high) + 1):
            if length < len(low):
                stepping_numbers = generate_stepping_numbers(length)
                for num in stepping_numbers:
                    if int(num) >= int(low) and int(num) <= int(high):
                        result += 1
            elif length == len(low):
                stepping_numbers = generate_stepping_numbers(length)
                for num in stepping_numbers:
                    if int(num) >= int(low) and int(num) <= int(high):
                        result += 1
            else:
                break

        return result % MOD

