        from collections import defaultdict

        def is_almost_equal(x: str, y: str) -> bool:
            # If lengths are different, they can't be made equal by swapping
            if len(x) != len(y):
                return False
            # Check if the sorted digits of x and y are the same
            return sorted(x) == sorted(y)

