        for idx, (x, y) in enumerate(coordinates):
            point_to_index[(x, y)] = idx

        # Sort the coordinates to make it easier to find increasing paths
        sorted_coords = sorted(coordinates)

        # Memoization dictionary to store the maximum path length starting from a point
        memo = {}

        def dfs(i, x, y):
            if (x, y) in memo:
                return memo[(x, y)]

            max_len = 1
            # Check all other points to see if they can be part of an increasing path
            for j in range(len(sorted_coords)):
                nx, ny = sorted_coords[j]
                if nx > x and ny > y:
                    current_len = 1 + dfs(j, nx, ny)
                    max_len = max(max_len, current_len)

            memo[(x, y)] = max_len
            return max_len

        # Start DFS from the point at index k
        start_point = coordinates[k]
        return dfs(point_to_index[start_point], start_point[0], start_point[1])

