class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for sc, tc in zip(s, t):
            if sc == tc:
                continue
            # Calculate the number of steps needed to shift from sc to tc
            # Using modular arithmetic to handle circular nature of alphabet
            steps_next = (ord(tc) - ord(sc)) % 26
            steps_prev = (ord(sc) - ord(tc)) % 26

            # Choose the cheaper option between next and previous shift
            if steps_next == 0:
                total_cost += 0
            elif steps_prev == 0:
                total_cost += 0
            else:
                cost_next = steps_next * nextCost[ord(sc) - ord('a')]
                cost_prev = steps_prev * previousCost[ord(sc) - ord('a')]
                total_cost += min(cost_next, cost_prev)
        return total_cost

