class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        result = []
        count = 0

        for index, color in queries:
            prev_color = nums[index]
            # Check neighbors before updating
            if index > 0 and prev_color != 0 and nums[index - 1] == prev_color:
                count -= 1
            if index < n - 1 and prev_color != 0 and nums[index + 1] == prev_color:
                count -= 1

            # Update the color
            nums[index] = color

            # Check neighbors after updating
            if index > 0 and nums[index - 1] == color:
                count += 1
            if index < n - 1 and nums[index + 1] == color:
                count += 1

            result.append(count)

        return result

