class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)  # dp[i] is the minimum extra characters up to index i

        # Preprocess dictionary into a set for O(1) lookups
        word_set = set(dictionary)

        for i in range(1, n + 1):
            # If the substring ending at i is in the dictionary, we can take it and add 0 extra chars
            if s[:i] in word_set:
                dp[i] = 0
            else:
                # Try all possible previous positions to see if we can find a valid word
                dp[i] = dp[i - 1] + 1  # Assume current character is extra
                for j in range(1, i):
                    if s[j:i] in word_set:
                        dp[i] = min(dp[i], dp[j] + 0)

        return dp[n]

