class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)
        dict_set = set(dictionary)

        for i in range(1, n + 1):
            # Initialize with the previous value plus 1 (current character is extra)
            dp[i] = dp[i-1] + 1
            # Check all possible substrings ending at position i
            for j in range(i):
                substr = s[j:i]
                if substr in dict_set:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

