        for i in range(1, n + 1):
            # Default case: current character is extra
            dp[i] = dp[i-1] + 1
            # Check all words in the dictionary
            for word in dictionary:
                l = len(word)
                if i - l >= 0:
                    if s[i - l:i] == word:
                        dp[i] = min(dp[i], dp[i - l])
