class Solution:
    def maximumTotalDamage(self, power: List[int]) -> int:
        count = Counter(power)
        sorted_powers = sorted(count.keys())
        n = len(sorted_powers)
        if n == 0:
            return 0
        dp = [0] * n
        for i in range(n):
            current_val = sorted_powers[i]
            current_total = current_val * count[current_val]
            target = current_val - 3
            pos = bisect.bisect_right(sorted_powers, target)
            if pos == 0:
                prev_max = 0
            else:
                prev_max = dp[pos - 1]
            candidate = prev_max + current_total
            if i == 0:
                dp[i] = candidate
            else:
                dp[i] = max(dp[i-1], candidate)
        return dp[-1]

