class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            s_list[i] = str(int(s_list[i]) - 1)
            result = ''.join(s_list)
            if result[0] == '0':
                first_non_zero = 0
                while first_non_zero < len(result) and result[first_non_zero] == '0':
                    first_non_zero += 1
                if first_non_zero == len(result):
                    return '0'
                else:
                    return result[first_non_zero:]
            else:
                return result

        def count(n_str):
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, prev_digit):
                if pos == len(n_str):
                    return 1 if prev_digit != -1 else 0
                res = 0
                max_digit = int(n_str[pos]) if tight else 9
                for d in range(0, max_digit + 1):
                    new_tight = tight and (d == max_digit)
                    if prev_digit == -1:
                        new_prev = -1 if d == 0 else d
                        res += dp(pos + 1, new_tight, new_prev)
                    else:
                        if abs(d - prev_digit) == 1:
                            res += dp(pos + 1, new_tight, d)
                    res %= MOD
                return res % MOD

            return dp(0, True, -1)

        count_high = count(high)
        low_minus_1 = subtract_one(low)
        count_low_minus_1 = count(low_minus_1)
        return (count_high - count_low_minus_1) % MOD

