class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Step 1: Find all valid rotations r
        valid_rs = self.find_valid_rotations(s, t, n)
        if not valid_rs:
            return 0

        # Step 2: Compute the formula components
        m = n
        pow_m_minus_1_k = pow(m - 1, k, MOD)

        # Compute pow_neg1_k
        if k % 2 == 0:
            pow_neg1_k = 1
        else:
            pow_neg1_k = MOD - 1

        inv_m = pow(m, MOD - 2, MOD)

        total = 0
        for r in valid_rs:
            if r == 0:
                numerator = (pow_neg1_k * (m - 1) + pow_m_minus_1_k) % MOD
            else:
                numerator = (pow_m_minus_1_k - pow_neg1_k) % MOD
            # Ensure non-negative
            numerator = (numerator + MOD) % MOD
            term = numerator * inv_m % MOD
            total = (total + term) % MOD

        return total

    def find_valid_rotations(self, s: str, t: str, n: int) -> list:
        if len(t) != n:
            return []
        s_concat = s + s
        P = t + '#' + s_concat
        m = len(t)
        len_P = len(P)
        Z = self.compute_z(P)
        valid_rs = []
        start_in_P = m + 1  # Start of s_concat in P

        for i in range(start_in_P, len_P):
            if Z[i] >= m:
                idx_in_s_concat = i - (m + 1)
                if 0 <= idx_in_s_concat < n:
                    valid_rs.append(idx_in_s_concat)
        return valid_rs

    def compute_z(self, s: str) -> list:
        n = len(s)
        Z = [0] * n
        l, r = 0, 0
        for i in range(1, n):
            if i <= r:
                Z[i] = min(r - i + 1, Z[i - l])
            while i + Z[i] < n and s[Z[i]] == s[i + Z[i]]:
                Z[i] += 1
            if i + Z[i] - 1 > r:
                l = i
                r = i + Z[i] - 1
        return Z

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count_stepping(l):
            dp = [[0] * 10 for _ in range(l + 1)]
            for d in range(1, 10):
                dp[1][d] = 1
            for i in range(2, l + 1):
                for d in range(10):
                    for prev_d in [d - 1, d + 1]:
                        if 0 <= prev_d <= 9:
                            dp[i][d] += dp[i - 1][prev_d]
                    dp[i][d] %= MOD
            return sum(dp[l]) % MOD

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            s_list[i] = str(int(s_list[i]) - 1)
            res = ''.join(s_list).lstrip('0')
            if res == '':
                return '0'
            return res

        def count_exact_length(s):
            n = len(s)
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev_digit, tight):
                if pos == n:
                    return 1
                limit = int(s[pos]) if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    new_tight = tight and (d == limit)
                    if pos == 0:
                        if d == 0:
                            continue
                        total += dp(pos + 1, d, new_tight)
                    else:
                        if abs(d - prev_digit) != 1:
                            continue
                        total += dp(pos + 1, d, new_tight)
                    total %= MOD
                return total % MOD

            return dp(0, 0, True)

        def helper(s):
            L = len(s)
            total = 0
            for l in range(1, L):
                total += count_stepping(l)
                total %= MOD
            total += count_exact_length(s)
            total %= MOD
            return total

        count_high = helper(high)
        low_minus_1 = subtract_one(low)
        if low_minus_1 == '0':
            count_low = 0
        else:
            count_low = helper(low_minus_1)
        ans = (count_high - count_low) % MOD
        return ans

