class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        heap = []
        for i in range(n):
            heapq.heappush(heap, (i, baskets[i]))

        unplaced = 0
        for fruit in fruits:
            temp = []
            # Remove all baskets with capacity less than current fruit
            while heap and heap[0][1] < fruit:
                temp.append(heapq.heappop(heap))
            if not heap:
                unplaced += 1
            else:
                # Assign the leftmost available basket
                heapq.heappop(heap)
                # Push back the temporarily stored baskets
                for item in temp:
                    heapq.heappush(heap, item)
        return unplaced

