class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        m = len(grid)
        n = len(grid[0]) if m > 0 else 0

        # Collect all unique values from the grid
        unique_values = set()
        for row in grid:
            for val in row:
                unique_values.add(val)
        unique_values = sorted(unique_values)
        value_to_index = {val: idx for idx, val in enumerate(unique_values)}
        num_unique = len(unique_values)

        @lru_cache(maxsize=None)
        def dp(row: int, bitmask: int) -> int:
            if row == m:
                return 0
            max_score = 0

            # Option 1: Skip the current row
            max_score = max(max_score, dp(row + 1, bitmask))

            # Option 2: Take a value from the current row
            for val in set(grid[row]):
                idx = value_to_index[val]
                if not (bitmask & (1 << idx)):
                    new_bitmask = bitmask | (1 << idx)
                    current_score = val + dp(row + 1, new_bitmask)
                    max_score = max(max_score, current_score)

            return max_score

        return dp(0, 0)

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(n):
            dp[i+1] = dp[i] + 1  # default case: one extra character at position i

            for j in range(i + 1):
                word = s[j:i+1]
                if word in dictionary:
                    dp[i+1] = min(dp[i+1], dp[j])

        return dp[n]

