class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        result = []
        count = 0

        for index, color in queries:
            old_color = nums[index]
            # Check left neighbor
            if index > 0 and nums[index - 1] != 0 and nums[index - 1] == old_color:
                count -= 1
            # Check right neighbor
            if index < n - 1 and nums[index + 1] != 0 and nums[index + 1] == old_color:
                count -= 1

            # Update the color
            nums[index] = color

            # Check left neighbor again
            if index > 0 and nums[index - 1] != 0 and nums[index - 1] == color:
                count += 1
            # Check right neighbor again
            if index < n - 1 and nums[index + 1] != 0 and nums[index + 1] == color:
                count += 1

            result.append(count)

        return result

class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        max_len = 1  # Minimum length of a valid substring is 1
        n = len(s)

        # Sliding window approach
        left = 0
        repeat_count = 0

        for right in range(n):
            # Check if current and previous character are the same
            if right > 0 and s[right] == s[right - 1]:
                repeat_count += 1

            # If there are more than one repeated pairs, move left pointer
            while repeat_count > 1:
                if s[left] == s[left + 1]:
                    repeat_count -= 1
                left += 1

            # Update maximum length
            max_len = max(max_len, right - left + 1)

        return max_len

