                    else:
                        p = s + str(s[-1]) + s[::-1][:-1]
                    num = int(p)
                    if num < 10**9:
                        palindromes.add(num)
            return sorted(palindromes)

        palindromes = generate_palindromes()

        # Find median of nums to minimize cost
