class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def is_stepping(num: str) -> bool:
            for i in range(1, len(num)):
                if abs(int(num[i]) - int(num[i - 1])) != 1:
                    return False
            return True

        def count_upto(n: str) -> int:
            from collections import deque

            # dp[pos][prev_digit][leading_zero]
            # We use BFS to generate all stepping numbers up to n
            queue = deque()
            for d in range(10):
                queue.append((str(d), d, False))  # (number_str, last_digit, leading_zero)

            result = 0
            while queue:
                num_str, last_digit, leading_zero = queue.popleft()
                if len(num_str) > len(n):
                    continue
                if len(num_str) == len(n) and num_str > n:
                    continue
                if not leading_zero:
                    result = (result + 1) % MOD
                next_digits = []
                if last_digit > 0:
                    next_digits.append(last_digit - 1)
                if last_digit < 9:
                    next_digits.append(last_digit + 1)
                for nd in next_digits:
                    new_num = num_str + str(nd)
                    if len(new_num) <= len(n):
                        queue.append((new_num, nd, False))
            return result

        # Count stepping numbers up to high and subtract those up to low-1
        def subtract_one(s: str) -> str:
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return "0"  # This case shouldn't happen as per constraints
            s_list[i] = str(int(s_list[i]) - 1)
            return ''.join(s_list)

        count_high = count_upto(high)
        count_low_minus_1 = count_upto(subtract_one(low))
        return (count_high - count_low_minus_1) % MOD

class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        n = len(nums)
        min_diff = float('inf')
        ors = set()

        for i in range(n):
            new_ors = set()
            new_ors.add(nums[i])
            for val in ors:
                new_ors.add(val | nums[i])
            ors = new_ors
            for val in ors:
                min_diff = min(min_diff, abs(val - k))

        return min_diff

