class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Step 1: Find all valid rotations of s that match t
        # We will use a concatenated string to find all occurrences of t in s + s
        double_s = s + s
        target_positions = []
        for i in range(n):
            if double_s[i:i+n] == t:
                target_positions.append(i)

        # If there are no such positions, return 0
        if not target_positions:
            return 0

        # Step 2: Precompute the number of ways to reach each rotation after k operations
        # Let dp[i][j] be the number of ways to get from rotation i to rotation j in k steps
        # Since the number of possible rotations is at most n, we can use matrix exponentiation
        # First, build the transition matrix
        m = len(target_positions)
        transitions = [[0] * m for _ in range(m)]

        # For each rotation i, compute which other rotations it can transition to in one step
        for i in range(m):
            original_pos = target_positions[i]
            for l in range(1, n):  # l is the suffix length to move
                new_pos = (original_pos - l) % n
                for j in range(m):
                    if target_positions[j] == new_pos:
                        transitions[i][j] += 1
                        break

        # Step 3: Matrix exponentiation to raise the transition matrix to the power of k
        def mat_mult(a, b):
            res = [[0] * m for _ in range(m)]
            for i in range(m):
                for k in range(m):
                    if a[i][k] == 0:
                        continue
                    for j in range(m):
                        res[i][j] = (res[i][j] + a[i][k] * b[k][j]) % MOD
            return res

        def mat_pow(mat, power):
            result = [[0] * m for _ in range(m)]
            for i in range(m):
                result[i][i] = 1
            while power > 0:
                if power % 2 == 1:
                    result = mat_mult(result, mat)
                mat = mat_mult(mat, mat)
                power //= 2
            return result

        transition_matrix = mat_pow(transitions, k)

        # Step 4: The initial state is being at position 0 (rotation 0), so count the total number of ways
        result = 0
        for i in range(m):
            result = (result + transition_matrix[0][i]) % MOD

        return result

class Solution:
    def countPairs(self, nums: List[int]) -> int:
        def is_almost_equal(x: int, y: int) -> bool:
            # Convert numbers to strings with leading zeros to make them the same length
            x_str = str(x)
            y_str = str(y)
            if len(x_str) != len(y_str):
                return False

            # Generate all permutations of digits for x and check if any matches y
            from itertools import permutations
            for perm in permutations(x_str):
                if ''.join(perm) == y_str:
                    return True
            return False

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                if is_almost_equal(nums[i], nums[j]):
                    count += 1
        return count

