    def maxScore(self, grid: List[List[int]]) -> int:
        from collections import defaultdict

        # Flatten the grid and count the frequency of each value
        freq = defaultdict(int)
        for row in grid:
            for val in row:
                freq[val] += 1

        # Create a list of unique values sorted in descending order
        unique_values = sorted(freq.keys(), reverse=True)

        # Use a set to track selected values
        selected = set()
        score = 0

        # Iterate through each cell in the grid
        for row in grid:
            for val in row:
                if freq[val] == 1 and val not in selected:
                    selected.add(val)
                    score += val

