class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        # Sort the baskets to allow efficient allocation
        baskets.sort()
        unplaced = 0
        i = 0  # Pointer for baskets

        for fruit in fruits:
            # Find the leftmost basket that can hold this fruit
            while i < len(baskets) and baskets[i] < fruit:
                i += 1
            if i < len(baskets):
                # Place the fruit in the basket
                i += 1
            else:
                # No suitable basket found
                unplaced += 1

        return unplaced

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for sc, tc in zip(s, t):
            # Convert characters to their indices (0-25)
            s_idx = ord(sc) - ord('a')
            t_idx = ord(tc) - ord('a')

            # Calculate the forward and backward shifts
            forward_shift = (t_idx - s_idx) % 26
            backward_shift = (s_idx - t_idx) % 26

            # Choose the cheaper option between forward and backward shift
            if forward_shift < backward_shift:
                total_cost += forward_shift * nextCost[s_idx]
            else:
                total_cost += backward_shift * previousCost[s_idx]

        return total_cost

