                # Count the number of consecutive duplicate pairs
                for k in range(len(substr) - 1):
                    if substr[k] == substr[k + 1]:
                        count += 1
                        if count > 1:
                            break
                if count <= 1:
                    max_len = max(max_len, j - i + 1)

