class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        MOD = 10**9 + 7

        def max_subseq_sum(arr):
            n = len(arr)
            dp = [0] * n
            dp[0] = arr[0]
            for i in range(1, n):
                dp[i] = max(dp[i - 1], dp[i - 1] + arr[i])
            return dp[-1]

        # We will use a segment tree to maintain the max subsequence sum efficiently
        class SegmentTree:
            def __init__(self, data):
                self.n = len(data)
                self.tree = [0] * (4 * self.n)
                self.build(0, 0, self.n - 1, data)

            def build(self, node, l, r, data):
                if l == r:
                    self.tree[node] = (data[l], data[l])  # (take, not_take)
                    return
                mid = (l + r) // 2
                self.build(2 * node + 1, l, mid, data)
                self.build(2 * node + 2, mid + 1, r, data)
                left_take, left_notake = self.tree[2 * node + 1]
                right_take, right_notake = self.tree[2 * node + 2]
                take = max(left_notake + right_take, left_take + right_notake, left_take + right_take)
                notake = max(left_take, left_notake) + max(right_take, right_notake)
                self.tree[node] = (take, notake)

            def update(self, pos, val, node, l, r):
                if l == r:
                    self.tree[node] = (val, val)
                    return
                mid = (l + r) // 2
                if pos <= mid:
                    self.update(pos, val, 2 * node + 1, l, mid)
                else:
                    self.update(pos, val, 2 * node + 2, mid + 1, r)
                left_take, left_notake = self.tree[2 * node + 1]
                right_take, right_notake = self.tree[2 * node + 2]
                take = max(left_notake + right_take, left_take + right_notake, left_take + right_take)
                notake = max(left_take, left_notake) + max(right_take, right_notake)
                self.tree[node] = (take, notake)

            def query(self):
                return max(self.tree[0])

        st = SegmentTree(nums)
        res = 0
        for pos, x in queries:
            st.update(pos, x, 0, 0, len(nums) - 1)
            res = (res + st.query()) % MOD
        return res

