class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def is_stepping(num_str):
            for i in range(1, len(num_str)):
                if abs(int(num_str[i]) - int(num_str[i-1])) != 1:
                    return False
            return True

        def count_up_to(n_str):
            from collections import deque

            n = len(n_str)
            dp = [[[0] * 10 for _ in range(2)] for _ in range(n)]
            dp[0][0][0] = 1  # leading zero allowed at first position
            dp[0][1][int(n_str[0])] = 1

            for i in range(1, n):
                for tight in range(2):
                    for prev_digit in range(10):
                        cnt = dp[i-1][tight][prev_digit]
                        if cnt == 0:
                            continue
                        max_digit = int(n_str[i]) if tight else 9
                        for d in range(0, max_digit + 1):
                            new_tight = tight and (d == max_digit)
                            if d == 0 and i == 0:
                                continue  # skip leading zero
                            if i > 0 and d == 0 and prev_digit != 0:
                                continue  # skip leading zero after non-zero digit
                            if abs(d - prev_digit) == 1:
                                dp[i][new_tight][d] = (dp[i][new_tight][d] + cnt) % MOD

            total = 0
            for tight in range(2):
                for d in range(10):
                    total = (total + dp[n-1][tight][d]) % MOD
            return total

        def to_int(s):
            return int(s)

        def count_in_range(low_str, high_str):
            return (count_up_to(high_str) - count_up_to(str(to_int(low_str) - 1))) % MOD

        return count_in_range(low, high)

class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        import sys
        sys.setrecursionlimit(1000000)

        def is_palindrome(x: int) -> bool:
            s = str(x)
            return s == s[::-1]

        # Generate all palindromic numbers up to 10^9
        def generate_palindromes():
            palindromes = set()
            for length in range(1, 10):  # up to 10 digits
                for start in range(10**(length // 2)):
                    s = str(start)
                    if length % 2 == 0:
                        p = s + s[::-1]
                    else:
                        p = s + str(s[-1]) + s[::-1][:-1]
                    num = int(p)
                    if num < 10**9:
                        palindromes.add(num)
            return sorted(palindromes)

        palindromes = generate_palindromes()

        # Find the median of nums to minimize cost
        median = sorted(nums)[len(nums) // 2]

        # Find the closest palindrome to the median
        def find_closest_palindromes(target):
            left, right = 0, len(palindromes) - 1
            closest = []
            while left <= right:
                mid = (left + right) // 2
                if palindromes[mid] < target:
                    closest.append(palindromes[mid])
                    left = mid + 1
                else:
                    closest.append(palindromes[mid])
                    right = mid - 1
            return closest

        candidates = find_closest_palindromes(median)
        candidates += [min(candidates), max(candidates)]

        min_cost = float('inf')
        for candidate in candidates:
            cost = sum(abs(num - candidate) for num in nums)
            if cost < min_cost:
                min_cost = cost

        return min_cost

