class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for sc, tc in zip(s, t):
            # Convert characters to their indices in the alphabet (0-25)
            sc_idx = ord(sc) - ord('a')
            tc_idx = ord(tc) - ord('a')

            # Calculate the forward and backward shifts
            forward_shift = (tc_idx - sc_idx) % 26
            backward_shift = (sc_idx - tc_idx) % 26

            # Choose the minimum cost between forward and backward shifts
            if forward_shift < backward_shift:
                total_cost += forward_shift * nextCost[sc_idx]
            else:
                total_cost += backward_shift * previousCost[sc_idx]

        return total_cost

