class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from collections import defaultdict

        # Sort the coordinates by x and y to allow for efficient traversal
        points = sorted(coordinates, key=lambda p: (p[0], p[1]))

        # Map each point to its index in the original list
        point_to_index = {tuple(p): i for i, p in enumerate(points)}

        # Build a graph where each node points to its neighbors that are strictly increasing
        graph = defaultdict(list)
        n = len(points)

        for i in range(n):
            x1, y1 = points[i]
            for j in range(i + 1, n):
                x2, y2 = points[j]
                if x2 > x1 and y2 > y1:
                    graph[i].append(j)

        # Memoization cache for dynamic programming
        memo = {}

        def dfs(i):
            if i in memo:
                return memo[i]

            max_len = 1  # At least the point itself
            for neighbor in graph[i]:
                current_len = 1 + dfs(neighbor)
                max_len = max(max_len, current_len)

            memo[i] = max_len
            return max_len

        # Start DFS from the point at index k
        result = dfs(k)
        return result

