class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] + [float('inf')] * n  # dp[0] is 0, others initialized to infinity

        for i in range(1, n + 1):
            # Option 1: take current character as extra
            dp[i] = dp[i-1] + 1

            # Option 2: check all words in dictionary that can end at i
            for word in dictionary:
                l = len(word)
                if l <= i:
                    if s[i - l:i] == word:
                        dp[i] = min(dp[i], dp[i - l])

        return dp[n]

