class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Check if s and t have the same characters
        if sorted(s) != sorted(t):
            return 0

        ss = s + s
        occurrences = []
        start = 0
        while True:
            pos = ss.find(t, start)
            if pos == -1:
                break
            if pos < n:
                occurrences.append(pos)
            start = pos + 1

        if not occurrences:
            return 0

        pow_n_minus_1_k = pow(n-1, k, MOD)
        if k % 2 == 0:
            pow_neg1 = 1
        else:
            pow_neg1 = MOD - 1

        inv_n = pow(n, MOD-2, MOD)

        total = 0
        for R in occurrences:
            if R == 0:
                term = ((n-1) * pow_neg1) % MOD
                numerator = (pow_n_minus_1_k + term) % MOD
            else:
                numerator = (pow_n_minus_1_k - pow_neg1) % MOD
            ways = (numerator * inv_n) % MOD
            total = (total + ways) % MOD

        return total

