class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        class SegmentTree:
            def __init__(self, data):
                self.n = len(data)
                self.size = 1
                while self.size < self.n:
                    self.size <<= 1
                self.minf = float('-inf')
                self.tree = [self.minf] * (2 * self.size)
                for i in range(self.n):
                    self.tree[self.size + i] = data[i]
                for i in range(self.size - 1, 0, -1):
                    self.tree[i] = max(self.tree[2 * i], self.tree[2 * i + 1])

            def update(self, pos, value):
                pos += self.size
                self.tree[pos] = value
                pos //= 2
                while pos >= 1:
                    new_val = max(self.tree[2 * pos], self.tree[2 * pos + 1])
                    if self.tree[pos] == new_val:
                        break
                    self.tree[pos] = new_val
                    pos //= 2

            def query_first_ge(self, x):
                def recurse(node, node_left, node_right):
                    if node_left == node_right:
                        return node_left if self.tree[node] >= x else -1
                    mid = (node_left + node_right) // 2
                    left_node = 2 * node
                    right_node = 2 * node + 1
                    if self.tree[left_node] >= x:
                        left_result = recurse(left_node, node_left, mid)
                        if left_result != -1:
                            return left_result
                    if self.tree[right_node] >= x:
                        return recurse(right_node, mid + 1, node_right)
                    return -1
                return recurse(1, 0, self.size - 1)

        st = SegmentTree(baskets)
        unplaced = 0
        for fruit in fruits:
            idx = st.query_first_ge(fruit)
            if idx == -1:
                unplaced += 1
            else:
                st.update(idx, float('-inf'))
        return unplaced

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        if n == 0:
            return 0

        # Check if t is a rotation of s
        ss = s + s
        R = set()
        pos = ss.find(t)
        while pos != -1:
            if 0 <= pos < n:
                r = (n - pos) % n
                R.add(r)
            pos = ss.find(t, pos + 1)

        if not R:
            return 0

        # Precompute necessary powers
        pow_nmk = pow(n-1, k, MOD)
        if k % 2 == 0:
            pow_neg1_k_mod = 1
        else:
            pow_neg1_k_mod = MOD - 1

        # Compute modular inverse of n
        inv_n = pow(n, MOD - 2, MOD)

        total = 0
        for r in R:
            if r == 0:
                numerator = (pow_neg1_k_mod * (n - 1) + pow_nmk) % MOD
            else:
                numerator = (pow_nmk - pow_neg1_k_mod) % MOD
            term = (numerator * inv_n) % MOD
            total = (total + term) % MOD

        return total

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def subtract_one(s):
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return '0'
            s_list[i] = str(int(s_list[i]) - 1)
            res = ''.join(s_list).lstrip('0')
            return res if res != '' else '0'

        def count_up_to(s):
            len_s = len(s)
            digits = [int(c) for c in s]

            # Part 1: numbers with length less than len_s
            total_part1 = 0
            max_m = len_s
            dp_table = [[0] * 10 for _ in range(max_m + 1)]

            # Initialize for m=1
            for d in range(1, 10):
                dp_table[1][d] = 1

            # Fill dp_table for m >= 2
            for m in range(2, max_m + 1):
                for d in range(10):
                    val = 0
                    if d - 1 >= 0:
                        val += dp_table[m-1][d-1]
                    if d + 1 < 10:
                        val += dp_table[m-1][d+1]
                    dp_table[m][d] = val % MOD

            # Sum part1 for m from 1 to len_s - 1
            for m in range(1, len_s):
                current_sum = 0
                for d in range(10):
                    current_sum += dp_table[m][d]
                total_part1 = (total_part1 + current_sum) % MOD

            # Part 2: numbers with len_s digits and <= s
            n = len_s
            if n == 0:
                return total_part1

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev, is_tight):
                if pos == n:
                    return 1
                res = 0
                max_digit = digits[pos] if is_tight else 9

                candidates = []
                if prev - 1 >= 0:
                    candidates.append(prev - 1)
                if prev + 1 <= 9:
                    candidates.append(prev + 1)

                for d in candidates:
                    if d > max_digit:
                        continue
                    new_is_tight = is_tight and (d == max_digit)
                    res += dp(pos + 1, d, new_is_tight)
                    res %= MOD
                return res % MOD

            total_part2 = 0
            if len_s >= 1:
                first_digit_max = digits[0]
                for first_d in range(1, first_digit_max + 1):
                    new_is_tight = (first_d == digits[0])
                    total_part2 = (total_part2 + dp(1, first_d, new_is_tight)) % MOD

            total = (total_part1 + total_part2) % MOD
            return total

        low_minus_1 = subtract_one(low)
        count_high = count_up_to(high)
        count_low_minus_1 = count_up_to(low_minus_1)
        ans = (count_high - count_low_minus_1) % MOD
        return ans

