class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        dp = {frozenset(): 0}
        for row in grid:
            temp_dp = {}
            for state, total in dp.items():
                # Option 1: do not take anything from this row
                if state in temp_dp:
                    if total > temp_dp[state]:
                        temp_dp[state] = total
                else:
                    temp_dp[state] = total
                # Option 2: take each element in the row
                for val in row:
                    if val not in state:
                        new_state = frozenset(state | {val})
                        new_total = total + val
                        if new_state in temp_dp:
                            if new_total > temp_dp[new_state]:
                                temp_dp[new_state] = new_total
                        else:
                            temp_dp[new_state] = new_total
            dp = temp_dp.copy()
        return max(dp.values()) if dp else 0

