class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count_stepping_numbers_less_than(n_str):
            n = len(n_str)
            dp = [0] * 10  # dp[d]: number of stepping numbers ending in digit d and length < current position
            for i in range(1, 10):
                dp[i] = 1  # single-digit numbers are all stepping numbers

            total = sum(dp) % MOD

            for i in range(1, n):
                new_dp = [0] * 10
                for d in range(10):
                    if d > 0:
                        new_dp[d] += dp[d - 1]
                    if d < 9:
                        new_dp[d] += dp[d + 1]
                    new_dp[d] %= MOD
                dp = new_dp
                total = (total + sum(dp)) % MOD

            # Now handle numbers with the same length as n_str
            used = set()
            for i in range(n):
                for d in range(10):
                    if i == 0 and d == 0:
                        continue  # skip leading zero
                    if d in used:
                        continue
                    if i == 0:
                        prefix = str(d)
                    else:
                        prefix = n_str[:i] + str(d)

                    if len(prefix) != len(n_str):
                        continue

                    if prefix > n_str:
                        break
                    if i == 0:
                        valid = True
                    else:
                        prev_digit = int(n_str[i-1])
                        curr_digit = d
                        if abs(prev_digit - curr_digit) != 1:
                            continue
                    used.add(d)
            return total

        result = (count_stepping_numbers_less_than(high) - count_stepping_numbers_less_than(low) + MOD) % MOD
        if self.is_stepping_number(low):
            result = (result + 1) % MOD
        return result

    def is_stepping_number(self, num_str):
