class Solution:
    def countPairs(self, nums: List[int]) -> int:
        from collections import Counter

        def get_digit_counts(n):
            digits = list(str(n))
            return tuple(sorted(digits))  # sorted to normalize the digit order

        # Count frequency of each normalized digit pattern
        freq = Counter()
        for num in nums:
            key = get_digit_counts(num)
            freq[key] += 1

        res = 0
        # For each unique digit pattern, calculate number of pairs
        for count in freq.values():
            res += count * (count - 1) // 2

        return res

