class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(n - 1, -1, -1):
            dp[i] = dp[i + 1]  # Start with one extra character

            for word in dictionary:
                if s.startswith(word, i):
                    if i + len(word) <= n:
                        dp[i] = max(dp[i], len(word) + dp[i + len(word)] - len(word))

        return len(s) - dp[0]

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for sc, tc in zip(s, t):
            i = ord(sc) - ord('a')
            j = ord(tc) - ord('a')

            if i == j:
                continue

            dist_forward = (j - i) % 26
            dist_backward = (i - j) % 26

            # Choose the minimum cost between moving forward or backward
            min_cost = float('inf')
            if dist_forward > 0:
                min_cost = sum(nextCost[(i + k) % 26] for k in range(dist_forward))
            if dist_backward > 0:
                min_cost = min(min_cost, sum(previousCost[(i - k) % 26] for k in range(dist_backward)))

            total_cost += min_cost

        return total_cost

