class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        from functools import lru_cache

        rows, cols = len(grid), len(grid[0])

        # Flatten the grid with their coordinates
        cells = []
        for i in range(rows):
            for j in range(cols):
                cells.append((grid[i][j], i, j))

        # Sort cells by value descending to prioritize larger values
        cells.sort(reverse=True)

        # Map each unique value to its positions
        value_to_positions = {}
        for val, i, j in cells:
            if val not in value_to_positions:
                value_to_positions[val] = []
            value_to_positions[val].append((i, j))

        # Convert list of unique values in descending order
        unique_vals = sorted(set(val for val, _, _ in cells), reverse=True)

        @lru_cache(None)
        def dp(i, used_rows):
            if i == len(unique_vals):
                return 0
            val = unique_vals[i]
            max_score = dp(i + 1, used_rows)  # Skip this value
            for r, c in value_to_positions[val]:
                if not (used_rows & (1 << r)):  # If row r is not used
                    new_used_rows = used_rows | (1 << r)
                    max_score = max(max_score, val + dp(i + 1, new_used_rows))
            return max_score

        return dp(0, 0)

