    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        max_len = 1  # Minimum length of substring is 1
        count = 1  # Start with the first character
        prev_same = False  # Track if the last pair was the same

        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                if not prev_same:
                    count += 1
                    prev_same = True
                else:
                    # Found second consecutive duplicate, reset window from next character
                    max_len = max(max_len, count)
                    count = 1
                    prev_same = False
                    j = i - 1
                    while j > 0 and s[j] == s[j - 1]:
                        j -= 1
                    count = i - j
            else:
                count += 1
                prev_same = False
            max_len = max(max_len, count)

        return max_len

