class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from collections import defaultdict

        n = len(coordinates)
        target_point = coordinates[k]

        # Sort the coordinates for binary search later
        sorted_by_x = sorted(enumerate(coordinates), key=lambda x: (x[1][0], x[1][1]))
        sorted_by_y = sorted(enumerate(coordinates), key=lambda x: (x[1][1], x[1][0]))

        # Build index to coordinate map and reverse lookups
        index_to_coord = {i: coord for i, coord in enumerate(coordinates)}
        coord_to_index = {tuple(coord): i for i, coord in enumerate(coordinates)}

        # Use dynamic programming with memoization
        from functools import lru_cache

        @lru_cache(None)
        def dfs(i):
            x_i, y_i = coordinates[i]
            max_len = 1  # At least path of length 1 includes itself
            # Find all points (x_j, y_j) such that x_j > x_i and y_j > y_i
            # We can use binary search on sorted lists for efficiency
            j = next((idx for idx, (j_idx, (x_j, y_j)) in enumerate(sorted_by_x) if x_j > x_i and y_j > y_i), None)
            while j < n:
                j_idx, (x_j, y_j) = sorted_by_x[j]
                if x_j > x_i and y_j > y_i:
                    max_len = max(max_len, 1 + dfs(j_idx))
                j += 1
            return max_len

        @lru_cache(None)
        def dfs_rev(i):
            x_i, y_i = coordinates[i]
            max_len = 1
            # Find all points (x_j, y_j) such that x_j < x_i and y_j < y_i
            j = next((idx for idx, (j_idx, (x_j, y_j)) in enumerate(sorted_by_x) if x_j < x_i and y_j < y_i), None)
            while j >= 0:
                j_idx, (x_j, y_j) = sorted_by_x[j]
                if x_j < x_i and y_j < y_i:
                    max_len = max(max_len, 1 + dfs_rev(j_idx))
                j -= 1
            return max_len

        return dfs(k) + dfs_rev(k) - 1

class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        import sys

        def is_palindrome(n):
