class Solution:
    def maximumTotalDamage(self, power: List[int]) -> int:
        from collections import Counter

        count = Counter(power)
        sorted_powers = sorted(count.keys())

        dp = {}

        # Use dynamic programming with memoization to avoid recomputation
        def dfs(i):
            if i >= len(sorted_powers):
                return 0
            if i in dp:
                return dp[i]

            # Option 1: Skip current spell
            skip = dfs(i + 1)

            # Option 2: Take current spell
            take = count[sorted_powers[i]] * sorted_powers[i]

            # Check for conflicts (any adjacent or near values)
            next_i = i + 1
            while next_i < len(sorted_powers) and sorted_powers[next_i] - sorted_powers[i] <= 2:
                next_i += 1

            take += dfs(next_i)

            dp[i] = max(skip, take)
            return dp[i]

        return dfs(0)

class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def count_less_than(n_str):
            n_len = len(n_str)
            dp = [[0] * 10 for _ in range(n_len + 1)]

            # Initialize for length 1 numbers (1-digit stepping numbers)
            for d in range(1, 10):
                dp[1][d] = 1

            for length in range(2, n_len + 1):
                for digit in range(10):
                    if dp[length - 1][digit]:
                        next_digits = [digit + 1, digit - 1]
                        for nd in next_digits:
                            if 0 <= nd < 10:
                                dp[length][nd] = (dp[length][nd] + dp[length - 1][digit]) % MOD

            total = 0
            for length in range(1, n_len + 1):
                total = (total + sum(dp[length])) % MOD

            # Subtract numbers that are greater than or equal to the input number
            from collections import deque
            queue = deque()
            visited = set()

            for d in range(1, 10):
                queue.append(str(d))

            result = 0
            while queue:
                num = queue.popleft()
                if len(num) > n_len:
                    continue
                if len(num) == n_len and num >= n_str:
                    continue
                result = (result + 1) % MOD
                last_digit = int(num[-1])
                for nd in [last_digit + 1, last_digit - 1]:
                    if 0 <= nd < 10:
                        new_num = num + str(nd)
                        if (len(new_num), new_num) not in visited:
                            visited.add((len(new_num), new_num))
                            queue.append(new_num)
            return total - result

        # We compute count_less_than(high + '1') - count_less_than(low)
        upper = count_less_than(high + '1')
        lower = count_less_than(low)
        return (upper - lower + MOD) % MOD

