        # Sort the baskets to allow binary search for available basket
        baskets.sort()

        unplaced = 0

        for fruit in fruits:
            # Binary search for the smallest basket with capacity >= fruit
            left, right = 0, len(baskets)
            while left < right:
                mid = (left + right) // 2
                if baskets[mid] >= fruit:
                    right = mid
                else:
                    left = mid + 1
            if left < len(baskets):
                # Place the fruit in the found basket and remove it from the list
                baskets.pop(left)
            else:
                # No suitable basket found
                unplaced += 1

        return unplaced

class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Precompute the max non-adjacent sum for the entire array
        def max_non_adj_sum(arr):
            if not arr:
                return 0
            n = len(arr)
            dp0, dp1 = 0, 0
            for i in range(n):
                new_dp0 = max(dp0, dp1)
                new_dp1 = dp0 + arr[i]
                dp0, dp1 = new_dp0, new_dp1
            return max(dp0, dp1)

        # Initial full array result
        res = max_non_adj_sum(nums)

        # Since we need to handle each query and update the array,
        # and recompute the max sum after each update,
        # a naive approach would be O(Q*N), which is too slow for N ~ 5e4.
        # So we use a segment tree with lazy propagation to maintain max non-adjacent sum efficiently.

        class SegmentTreeNode:
            def __init__(self, l, r):
                self.l = l
                self.r = r
                self.left = None
                self.right = None
                self.max_val = 0

        class SegmentTree:
            def __init__(self, arr):
                self.n = len(arr)
                self.root = self.build(0, self.n - 1, arr)

            def build(self, l, r, arr):
                node = SegmentTreeNode(l, r)
                if l == r:
                    node.max_val = arr[l]
                    return node
                mid = (l + r) // 2
                node.left = self.build(l, mid, arr)
                node.right = self.build(mid + 1, r, arr)
                node.max_val = max(node.left.max_val, node.right.max_val)
                return node

            def update(self, pos, val):
                self._update(self.root, pos, val)

            def _update(self, node, pos, val):
                if node.l == node.r:
                    node.max_val = val
                    return
                if pos <= node.left.r:
                    self._update(node.left, pos, val)
                else:
                    self._update(node.right, pos, val)
                node.max_val = max(node.left.max_val, node.right.max_val)

            def query(self):
                return self._query(self.root)

            def _query(self, node):
                if node.l == node.r:
                    return node.max_val
                left_max = self._query(node.left)
                right_max = self._query(node.right)
                return max(left_max, right_max)

        # We can't directly use a segment tree for this problem because it's more complex than just max or sum.
        # Instead, we will simulate the process by maintaining two arrays:
        # dp0[i] = max sum up to i where the last element is not included
        # dp1[i] = max sum up to i where the last element is included

        dp0 = [0] * (n + 1)
        dp1 = [0] * (n + 1)

        for i in range(n):
            dp0[i+1] = max(dp0[i], dp1[i])
            dp1[i+1] = dp0[i] + nums[i]

        total = max(dp0[n], dp1[n])

        for pos, x in queries:
            old_val = nums[pos]
            nums[pos] = x
            diff = x - old_val

            for i in range(pos + 1, n + 1):
                dp0[i] = max(dp0[i-1], dp1[i-1])
                dp1[i] = dp0[i-1] + nums[i-1]

            total += max(dp0[n], dp1[n])
            total %= MOD

        return total

