class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            # Default case: take the previous extra +1
            dp[i] = dp[i-1] + 1

