class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        # Precompute prefix sums for next and previous costs
        prefix_next = [0] * 27
        for i in range(26):
            prefix_next[i+1] = prefix_next[i] + nextCost[i]

        prefix_prev = [0] * 27
        for i in range(26):
            prefix_prev[i+1] = prefix_prev[i] + previousCost[i]

        total = 0
        for sc, tc in zip(s, t):
            s_pos = ord(sc) - ord('a')
            t_pos = ord(tc) - ord('a')
            if s_pos == t_pos:
                continue

            # Compute cost_forward
            delta_forward = (t_pos - s_pos) % 26
            if delta_forward == 0:
                cost_forward = 0
            else:
                if t_pos >= s_pos:
                    cost_forward = prefix_next[t_pos] - prefix_next[s_pos]
                else:
                    cost_forward = (prefix_next[26] - prefix_next[s_pos]) + (prefix_next[t_pos] - prefix_next[0])

            # Compute cost_backward
            delta_backward = (s_pos - t_pos) % 26
            if delta_backward == 0:
                cost_backward = 0
            else:
                if t_pos + 1 <= s_pos:
                    cost_backward = prefix_prev[s_pos + 1] - prefix_prev[t_pos + 1]
                else:
                    cost_backward = (prefix_prev[26] - prefix_prev[t_pos + 1]) + (prefix_prev[s_pos + 1] - prefix_prev[0])

            total += min(cost_forward, cost_backward)

        return total

