class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        if len(t) != n:
            return 0

        s_concat = s + s
        positions = []
        pos = s_concat.find(t)
        while pos != -1:
            if pos < n:
                positions.append(pos)
            pos = s_concat.find(t, pos + 1)

        if not positions:
            return 0

        a = n - 1
        a_pow_k = pow(a, k, MOD)
        sign = 1 if k % 2 == 0 else -1
        sign = sign % MOD

        inv_n = pow(n, MOD - 2, MOD)
        total = 0

        for m in positions:
            if m == 0:
                numerator = (a_pow_k + a * sign) % MOD
            else:
                numerator = (a_pow_k - sign) % MOD
            numerator = (numerator + MOD) % MOD  # Ensure non-negative
            term = (numerator * inv_n) % MOD
            total = (total + term) % MOD

        return total

