class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        sorted_nums = sorted(nums)
        n = len(nums)
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i+1] = prefix_sum[i] + sorted_nums[i]

        # Determine medians
        if n % 2 == 1:
            medians = [sorted_nums[n//2]]
        else:
            medians = [sorted_nums[(n//2)-1], sorted_nums[n//2]]

        # Generate candidate palindromes
        candidates = set()
        for m in medians:
            l = len(str(m))
            for length in [l-1, l, l+1]:
                if length < 1:
                    continue
                palindromes = self.generate_palindromes(length)
                candidates.update(palindromes)

        # Calculate the minimum cost
        min_cost = float('inf')
        for y in candidates:
            pos = bisect.bisect_left(sorted_nums, y)
            sum_left = y * pos - prefix_sum[pos]
            sum_right = (prefix_sum[n] - prefix_sum[pos]) - y * (n - pos)
            total = sum_left + sum_right
            if total < min_cost:
                min_cost = total

        return min_cost

    def generate_palindromes(self, length: int) -> List[int]:
        palindromes = []
        if length == 0:
            return []
        if length == 1:
            for i in range(1, 10):
                palindromes.append(i)
            return palindromes
        half_len = (length + 1) // 2
        start = 10 ** (half_len - 1)
        end = 10 ** half_len
        for prefix in range(start, end):
            s = str(prefix)
            if length % 2 == 0:
                pal_str = s + s[::-1]
            else:
                pal_str = s + s[:-1][::-1]
            pal_num = int(pal_str)
            palindromes.append(pal_num)
        return palindromes

