        n = len(s)
        dp = [0] * (n + 1)  # dp[i] is the min extra chars for s[0..i-1]

        # Preprocess dictionary into a set for O(1) lookups
        word_set = set(dictionary)

        for i in range(1, n + 1):
            # Case 1: current character is extra
            dp[i] = dp[i - 1] + 1

            # Case 2: check if any word ends at position i
            for j in range(i):
                substr = s[j:i]
                if substr in word_set:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

