    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        def is_stepping(num: str) -> bool:
            for i in range(1, len(num)):
                if abs(int(num[i]) - int(num[i-1])) != 1:
                    return False
            return True

        def count_stepping_numbers(limit: str) -> int:
            from collections import deque
            queue = deque()
            count = 0

            for d in range(1, 10):
                if is_stepping(str(d)):
                    queue.append((str(d), 1))
                    count += 1

            while queue:
                num_str, length = queue.popleft()
                if length == len(limit):
                    if int(num_str) <= int(limit):
                        count += 1
                    continue
                for d in range(0, 10):
                    if abs(int(num_str[-1]) - d) == 1:
                        new_num = num_str + str(d)
                        if is_stepping(new_num):
                            queue.append((new_num, length + 1))
                            count += 1

            return count

        # Count stepping numbers from 0 to high
        count_high = count_stepping_numbers(high)

        # Count stepping numbers from 0 to low-1
        # To handle low-1, we need to decrement the string
        def decrement_string(s: str) -> str:
            s_list = list(s)
            i = len(s_list) - 1
            while i >= 0 and s_list[i] == '0':
                s_list[i] = '9'
                i -= 1
            if i < 0:
                return '0'  # This case shouldn't happen as per constraints
            s_list[i] = str(int(s_list[i]) - 1)
            return ''.join(s_list)

        low_minus_1 = decrement_string(low)
        count_low_minus_1 = count_stepping_numbers(low_minus_1)

        return (count_high - count_low_minus_1) % MOD

