class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(x: int) -> bool:
            return str(x) == str(x)[::-1]

        # Generate palindromic numbers around the median of nums
        # We'll generate palindromes near the median to minimize cost
        median = nums[len(nums) // 2]
        min_pal = max(1, median - 1000)
        max_pal = median + 1000

        # Generate all palindromic numbers in the range [min_pal, max_pal]
        palindromes = set()
        for i in range(1, 10):
            for j in range(10):
                for k in range(10):
                    for l in range(10):
                        for m in range(10):
                            for n in range(10):
                                num = int(str(i) + str(j) + str(k) + str(l) + str(m) + str(n))
                                if is_palindrome(num):
                                    palindromes.add(num)

        # Also check numbers with fewer digits
        for i in range(1, 10):
            for j in range(10):
                for k in range(10):
                    num = int(str(i) + str(j) + str(k))
                    if is_palindrome(num):
                        palindromes.add(num)
        for i in range(1, 10):
            for j in range(10):
                num = int(str(i) + str(j))
                if is_palindrome(num):
                    palindromes.add(num)
        for i in range(1, 10):
            num = int(str(i))
            if is_palindrome(num):
                palindromes.add(num)

        # Remove palindromes outside the range
        palindromes = [p for p in palindromes if min_pal <= p <= max_pal]

        # If no palindromes found, try expanding the range
        if not palindromes:
            min_pal = max(1, median - 2000)
            max_pal = median + 2000
            palindromes = set()
            for i in range(1, 10):
                for j in range(10):
                    for k in range(10):
                        for l in range(10):
                            for m in range(10):
                                for n in range(10):
                                    num = int(str(i) + str(j) + str(k) + str(l) + str(m) + str(n))
                                    if is_palindrome(num):
                                        palindromes.add(num)
            palindromes = [p for p in palindromes if min_pal <= p <= max_pal]

        # Calculate the minimum cost
        min_cost = inf
        for p in palindromes:
            cost = sum(abs(num - p) for num in nums)
            min_cost = min(min_cost, cost)

        return min_cost

class Solution:
    def shiftDistance(self, s: str, t: str, nextCost: List[int], previousCost: List[int]) -> int:
        total_cost = 0
        for sc, tc in zip(s, t):
            # Calculate the difference in positions
            s_idx = ord(sc) - ord('a')
            t_idx = ord(tc) - ord('a')

            # Calculate the number of shifts needed in both directions
            next_shifts = (t_idx - s_idx) % 26
            previous_shifts = (s_idx - t_idx) % 26

            # Choose the cheaper option
            if next_shifts * nextCost[s_idx] < previous_shifts * previousCost[s_idx]:
                total_cost += next_shifts * nextCost[s_idx]
            else:
                total_cost += previous_shifts * previousCost[s_idx]

        return total_cost

class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        n = len(s)
        dp = [0] * (n + 1)  # dp[i] is the minimum extra characters up to index i

        # Initialize dp[0] = 0 (no extra characters before the string starts)
        for i in range(1, n + 1):
            dp[i] = dp[i - 1] + 1  # Assume current character is extra

            # Check all possible substrings ending at i
            for j in range(i):
                substr = s[j:i]
                if substr in dictionary:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

