class Solution:
    def colorTheArray(self, n: int, queries: List[List[int]]) -> List[int]:
        nums = [0] * n
        result = []
        count = 0

        for index, color in queries:
            prev_color = nums[index]
            # Check left neighbor
            if index > 0:
                if prev_color == nums[index - 1]:
                    count -= 1
                if color == nums[index - 1]:
                    count += 1
            # Check right neighbor
            if index < n - 1:
                if prev_color == nums[index + 1]:
                    count -= 1
                if color == nums[index + 1]:
                    count += 1
            # Update the color
            nums[index] = color
            result.append(count)

        return result

