class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        from collections import defaultdict

        n = len(coordinates)
        # Map each coordinate to its index for quick lookup
        coord_to_idx = {(x, y): i for i, (x, y) in enumerate(coordinates)}

        # Sort the coordinates to enable efficient traversal
        sorted_coords = sorted(coordinates)

        # dp[i] will store the length of the longest increasing path starting at index i
        dp = [1] * n

        # We need to find the longest increasing path that includes coordinates[k]
        # So we will perform a topological sort and dynamic programming approach
        # We sort the coordinates by x and y to ensure we process smaller points first

        # We'll use a dictionary to store the maximum path length for each (x, y)
        # This helps us avoid recomputation
        memo = {}

        def dfs(i):
            if i in memo:
                return memo[i]
            x, y = coordinates[i]
            max_len = 1
            for j in range(n):
                if j == i:
                    continue
                # Check if (x, y) < (coordinates[j][0], coordinates[j][1])
                if coordinates[j][0] > x and coordinates[j][1] > y:
                    if dp[j] + 1 > max_len:
                        max_len = dp[j] + 1
            memo[i] = max_len
            return max_len

        # We need to ensure we process points in order of increasing x and y
        # So we sort the coordinates and then process them in that order
        sorted_coords = sorted(coordinates)
        for i in range(n):
            x, y = sorted_coords[i]
            for j in range(i + 1, n):
                if sorted_coords[j][0] > x and sorted_coords[j][1] > y:
                    dp[i] = max(dp[i], dp[j] + 1)

        # Now we perform DFS starting from the k-th coordinate
        # But since we sorted the coordinates, we need to find the index of coordinates[k] in sorted_coords
        target = coordinates[k]
        target_idx = coord_to_idx[target]

        # We need to perform a DFS from the target index
        # However, since we have already computed dp values, we can just return dp[target_idx]
        # But wait, dp is computed based on sorted order, not original indices
        # So we need to recompute dp based on the original indices

        # Let's recompute dp correctly
        dp = [1] * n
        for i in range(n):
            x, y = coordinates[i]
            for j in range(n):
                if i == j:
                    continue
                if coordinates[j][0] > x and coordinates[j][1] > y:
                    dp[i] = max(dp[i], dp[j] + 1)

        return dp[target_idx]

